                return step_toward(self_pos, target)
            return step_away(self_pos, opp_pos)
        return step_toward(self_pos, opp_pos)

    # Territory control
    if env == "territory_control":
        target = best_target(unclaimed, self_pos)
        if target is None:
            target = best_target(enemy_terr, self_pos)
        if target is None and w and h:
            target = (w // 2, h // 2)
        if target is not None:
            return step_toward(self_pos, target)
        return step_toward(self_pos, opp_pos)

